package AirIoniserSystem {
    private import ScalarValues::*;
    private import ISQ::*;
    private import SI::*;
    private import Time::*;

    // Value types and enumerations
    attribute def IonConcentration :> Real;
    attribute def VoltageValue :> Real;
    attribute def AirFlowRate :> Real;

    enum def OperatingMode {
        off;
        standby;
        low;
        medium;
        high;
        auto;
    }

    enum def AirQualityLevel {
        excellent;
        good;
        moderate;
        poor;
        hazardous;
    }

    // Item definitions
    item def Air {
        attribute particleCount : Real;
        attribute ionLevel : IonConcentration;
        attribute qualityLevel : AirQualityLevel;
    }

    item def NegativeIon {
        attribute charge : Real;
    }

    // Component definitions
    part def HighVoltageGenerator {
        attribute outputVoltage : VoltageValue;
        attribute powerConsumption : PowerValue;

        port voltageOut;
    }

    part def IonEmitter {
        attribute emissionRate : IonConcentration;
        attribute needleCount : Integer;

        port voltageIn;
        port ionOut;
    }

    part def AirQualitySensor {
        attribute sensitivity : Real;
        attribute measurementRange : IonConcentration;

        port airIn;
        port dataOut;

        action measureAirQuality {
            in airSample : Air;
            out qualityReading : AirQualityLevel;
            out ionReading : IonConcentration;
        }
    }

    part def Fan {
        attribute speed : Real;
        attribute flowRate : AirFlowRate;
        attribute maxFlowRate : AirFlowRate;

        port airIn;
        port airOut;
        port controlIn;

        action circulateAir {
            in targetSpeed : Real;
            out actualFlowRate : AirFlowRate;
        }
    }

    part def ControlUnit {
        attribute currentMode : OperatingMode;
        attribute targetIonLevel : IonConcentration;

        port sensorIn;
        port fanControlOut;
        port generatorControlOut;
        port userInterface;

        action processControl {
            in sensorData : AirQualityLevel;
            in userMode : OperatingMode;
            out fanSpeed : Real;
            out generatorVoltage : VoltageValue;
        }
    }

    part def PowerSupply {
        attribute inputVoltage : VoltageValue;
        attribute outputVoltage : VoltageValue;
        attribute maxCurrent : Real;

        port powerIn;
        port powerOut;
    }

    part def FilterAssembly {
        attribute filterEfficiency : Real;
        attribute filterLifespan : DurationValue;

        port airIn;
        port airOut;

        action filterAir {
            in untreatedAir : Air;
            out filteredAir : Air;
        }
    }

    // Main system definition
    part def AirIoniser {
        attribute operationalStatus : OperatingMode;
        attribute coverageArea : AreaValue;
        attribute totalMass : MassValue;

        part powerSupply : PowerSupply {
            attribute :>> inputVoltage = 120.0;
            attribute :>> outputVoltage = 12.0;
            attribute :>> maxCurrent = 2.0;
        }

        part controller : ControlUnit {
            attribute :>> currentMode = OperatingMode::standby;
            attribute :>> targetIonLevel = 5000.0;
        }

        part hvGenerator : HighVoltageGenerator {
            attribute :>> outputVoltage = 5000.0;
            attribute :>> powerConsumption = 15.0 [W];
        }

        part emitter : IonEmitter {
            attribute :>> emissionRate = 8000000.0;
            attribute :>> needleCount = 6;
        }

        part airSensor : AirQualitySensor {
            attribute :>> sensitivity = 0.95;
            attribute :>> measurementRange = 10000000.0;
        }

        part circulationFan : Fan {
            attribute :>> speed = 0.0;
            attribute :>> flowRate = 0.0 [m^3/s];
            attribute :>> maxFlowRate = 0.15 [m^3/s];
        }

        part preFilter : FilterAssembly {
            attribute :>> filterEfficiency = 0.85;
            attribute :>> filterLifespan = 2160.0 [h];
        }

        // Connections
        connection powerSupplyToGenerator connect 
            powerSupply.powerOut to hvGenerator;

        connection generatorToEmitter connect 
            hvGenerator.voltageOut to emitter.voltageIn;

        connection sensorToController connect 
            airSensor.dataOut to controller.sensorIn;

        connection controllerToFan connect 
            controller.fanControlOut to circulationFan.controlIn;

        connection controllerToGenerator connect 
            controller.generatorControlOut to hvGenerator;

        connection filterToFan connect 
            preFilter.airOut to circulationFan.airIn;

        connection fanToEmitter connect 
            circulationFan.airOut to emitter;

        connection emitterToSensor connect 
