package 'Air Ionizer System' {
	private import ISQ::*;
	private import SI::*;
	private import ScalarValues::*;

	// --- Value Type, Item, and Interface Definitions ---
	value def VolumeRatio :> Ratio;

	item def Air {
		attribute particulateConcentration : MassConcentration;
		attribute ozoneConcentration : VolumeRatio;
	}

	interface def AirInterface {
		flow air : Air;
	}

	interface def ElectricalInterface {
		flow voltage : ElectricPotential;
	}

	interface def ControlInterface {
		out isOn : Boolean;
	}

	// --- Action and Behavior Definitions ---
	action def DrawInAir {
		in airToDraw : Air;
		out drawnAir : Air;
		assert constraint { drawnAir == airToDraw }
	}

	action def IonizeAir {
		in uncleanAir : Air;
		out ionizedAir : Air;

		assert constraint ParticulateReduction {
			ionizedAir.particulateConcentration <= uncleanAir.particulateConcentration * 0.1
		}

		assert constraint OzoneByproduct {
			// Model ozone generation as an additive process, constrained below the limit.
			// 0.05 ppm = 50 ppb = 5e-8. Let's say it adds 40ppb.
			ionizedAir.ozoneConcentration == uncleanAir.ozoneConcentration + 4e-8
		}
	}

	action def ExpelAir {
		in airToExpel : Air;
		out expelledAir : Air;
		assert constraint { expelledAir == airToExpel }
	}

	reception def PowerOn;
	reception def PowerOff;

	// --- Component Definitions ---
	part def Fan {
		attribute nominalFlowRate : VolumeFlowRate = 0.05 [m^3/s];
	}

	part def IonizationNeedleArray {
		attribute requiredVoltage : ElectricPotential = -5 [kV];
	}

	part def PowerSupply {
		out port powerOut : ElectricalInterface;
		attribute outputVoltage : ElectricPotential = -5 [kV];

		assert constraint VoltageOutput {
			powerOut.voltage == outputVoltage
		}
	}

	part def ControlUnit {
		out port controlOut : ControlInterface;

		accepts PowerOn, PowerOff;

		state machine ControllerLogic {
			initial state Off {
				entry do { controlOut.isOn = false; }
			}
			state Active {
				entry do { controlOut.isOn = true; }
			}

			transition from Off to Active on PowerOn;
			transition from Active to Off on PowerOff;
		}
	}

	// --- System Definition ---
	part def AirIonizer {
		in port airInlet : AirInterface;
		out port airOutlet : AirInterface;
		in port powerInlet : ElectricalInterface;
		in port controlIn :> ~ControlInterface;

		part fan : Fan;
		part needles : IonizationNeedleArray;

		action operate {
			first draw : DrawInAir {
				perform by fan;
				in airToDraw from airInlet.air;
			}
			then ionize : IonizeAir {
				perform by needles;
				in uncleanAir = draw.drawnAir;
			}
			then expel : ExpelAir {
				perform by fan;
				in airToExpel = ionize.ionizedAir;
			}

			out expel.expelledAir to airOutlet.air;
		}

		state machine IonizerState {
			initial state Idle;
			state Operating {
				do operate;
			}

			transition from Idle to Operating when controlIn.isOn;
			transition from Operating to Idle when not controlIn.isOn;
		}

		assert constraint VoltageRequirement { needles.requiredVoltage == powerInlet.voltage }
	}

	// --- System Assembly and Requirements ---
	part system {
		part ionizer : AirIonizer;
		part power : PowerSupply;
		part controller : ControlUnit;

		in port systemAirIn : AirInterface;
		out port systemAirOut : AirInterface;

		connect systemAirIn to ionizer.airInlet;
		connect ionizer.airOutlet to systemAirOut;
		connect power.powerOut to ionizer.powerInlet;
		connect controller.controlOut to ionizer.controlIn;
	}

	requirement <'SYS-001'> HighEfficacyParticulateReduction {
		doc "The system shall reduce PM2.5 particulate concentration by at least 90%."
		subject s : system;

		require constraint EfficacyConstraint {
			s.systemAirOut.air.particulateConcentration <= s.systemAirIn.air.particulateConcentration * 0.1
		}
	}

	requirement <'SYS-002'> LowOzoneProduction {
		doc "The system shall produce an ozone concentration below 0.05 ppm."
		subject s : system;
		require constraint OzoneLimit {
			s.systemAirOut.air.ozoneConcentration <= 5e-8 // 0.05 ppm
		}
	}

	assume AmbientOzone {
		doc "Assume ambient ozone concentration is at most 10 ppb."
		subject s : system;
		assert constraint {
			s.systemAirIn.air.ozoneConcentration <= 1e-8 // 10 ppb
		}
	}

	satisfy HighEfficacyParticulateReduction by system.ionizer.operate.ionize.ParticulateReduction;
	satisfy LowOzoneProduction by system.ionizer.operate.ionize.OzoneByproduct, AmbientOzone;
}
